const keywords = [
  "properti",
  "pasar properti Indonesia",
  "harga rumah",
  "apartemen",
  "perumahan",
  "KPR",
  "pengembang properti",
  "investasi properti",
  "kawasan hunian"
];

return keywords.map(keyword => ({
  json: {
    keyword,
    url: `https://news.google.com/rss/search?q=${encodeURIComponent(
      `site:antaranews.com ${keyword}`
    )}&hl=id&gl=ID&ceid=ID:id`
  }
}));

const results = [];
const seen = new Set();

const propertyRegex =
  /\b(harga properti|harga rumah|harga apartemen|pasar properti|pasar perumahan|bisnis properti|investasi properti|sektor properti|industri properti|properti residensial|properti komersial|pengembang properti|developer properti|proyek properti|transaksi properti|penjualan properti|kredit pemilikan rumah|suku bunga KPR|rumah subsidi|perumahan subsidi|apartemen baru|pembangunan perumahan|kawasan perumahan|real estate|real estat|properti indonesia)\b/i;

const excludeRegex =
  /\b(kasus|tersangka|terdakwa|sidang|pengadilan|korupsi|pembunuhan|kecelakaan|kebakaran|bencana|sepak bola|liga|pemain|artis|penyanyi|film|festival|wali kota|bupati|gubernur|presiden|pemilu|pilkada|perang|konflik|polisi|narkoba|kriminal|pencurian|wisata|pariwisata|kuliner)\b/i;

const now = Date.now();
const maxAge = 30 * 24 * 60 * 60 * 1000;

function findArticles(obj) {
  if (!obj || typeof obj !== 'object') return;

  if (Array.isArray(obj)) {
    for (const item of obj) findArticles(item);
    return;
  }

  if (obj.title && obj.link) {
    const title = String(obj.title).trim();

    const link = typeof obj.link === 'object'
      ? obj.link.href || obj.link['#text'] || ''
      : String(obj.link);

    const description = String(
      obj.description || obj.contentSnippet || ''
    );

    const pubDate = obj.pubDate || '';

    const isAntara =
      /antaranews\.com/i.test(link) ||
      /-\s*ANTARA News(?:\s+[A-Za-z]+)?$/i.test(title);

    // Judul harus membahas pasar atau industri properti
    const isProperty = propertyRegex.test(title);

    const isExcluded = excludeRegex.test(title);

    // Hanya berita maksimal 30 hari
    const articleDate = Date.parse(pubDate);
    const isRecent =
      !pubDate ||
      (Number.isFinite(articleDate) &&
       now - articleDate <= maxAge &&
       now >= articleDate);

    if (
      isAntara &&
      isProperty &&
      !isExcluded &&
      isRecent &&
      !seen.has(link)
    ) {
      seen.add(link);

      results.push({
        json: {
          title,
          link,
          description,
          pubDate
        }
      });
    }
  }

  for (const value of Object.values(obj)) {
    if (value && typeof value === 'object') {
      findArticles(value);
    }
  }
}

for (const item of $input.all()) {
  findArticles(item.json);
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  const content = Array.isArray(data.content)
    ? data.content.join('\n')
    : String(data.content || '');

  const cleanedContent = content
    .replace(/\s+/g, ' ')
    .trim();

  const isValid =
    data.title &&
    data.image &&
    data.canonicalUrl &&
    cleanedContent.length >= 300;

  if (!isValid) continue;

  results.push({
    json: {
      title: data.title,
      description: data.description,
      image: data.image,
      publishedAt: data.publishedAt,
      canonicalUrl: data.canonicalUrl,
      content: cleanedContent
    }
  });
}

return results;

const html = $json.body || '';
const link = $json.link || '';

const timestamp = html.match(/data-n-a-ts="([^"]+)"/);
const signature = html.match(/data-n-a-sg="([^"]+)"/);

const articleId = link.match(/\/articles\/([^?]+)/)?.[1];

if (!timestamp || !signature || !articleId) {
  throw new Error('Google News parameters tidak lengkap');
}

return {
  json: {
    title: $json.title,
    link,
    description: $json.description,
    pubDate: $json.pubDate,
    articleId,
    timestamp: Number(timestamp[1]),
    signature: signature[1]
  }
};

