const raw = $json.response || '';

const clean = raw.replace(/^\)\]\}'\s*/, '').trim();

const frames = JSON.parse(clean);

const frame = frames.find(
  item =>
    Array.isArray(item) &&
    item[0] === 'wrb.fr' &&
    item[1] === 'Fbv4je'
);

if (!frame || !frame[2]) {
  throw new Error('Respons URL Google tidak ditemukan');
}

const result = JSON.parse(frame[2]);

if (result[0] !== 'garturlres' || !result[1]) {
  throw new Error('URL artikel tidak ditemukan');
}

const articleUrl = result[1].trim();

const isAntaraArticle =
  /^https:\/\/(?:www\.|m\.)?antaranews\.com\/(?:amp\/)?berita\/\d+\//i
    .test(articleUrl);

if (!isAntaraArticle) {
  throw new Error('URL bukan artikel ANTARA: ' + articleUrl);
}

return {
  json: {
    title: $json.title,
    pubDate: $json.pubDate,
    articleUrl
  }
};

return {
  json: {
    title: $json.title,
    description: $json.description,
    content: $json.content,
    image: $json.image,
    publishedAt: $json.publishedAt,
    canonicalUrl: $json.canonicalUrl,
    agentInstructions: $json.agentInstructions,
    contentGuidelines: $json.contentGuidelines
  }
};

const raw = $json.output;

const clean = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

const data = JSON.parse(clean);

return data.slides.map((slide, index) => ({
  json: {
    ...slide,
    slideNumber: index + 1,
    caption: data.caption,
    carousel: data.carousel
  }
}));
